                case "__doc__":
                    result = _type?.GetField(name, Members) is FieldInfo metadata ? metadata.GetValue(null) :
                        name == "__name__" ? _name : _source?.DocString;
                    return true;
                case "__file__" when __file__ != null: result = __file__; return true;
            }
            result = null;
            if (_type == null || !IsModuleName(name)) return false;
            if (_type == typeof(Typhon.Stdlib.os_) && name == "path") { result = Typhon.Stdlib.os_.__path_module__; return true; }
            if (_type == typeof(Typhon.Stdlib.builtins) && name == "print") { result = Builtins.__print_value(); return true; }
            if (_type == typeof(Typhon.Stdlib.builtins) && Typhon.Stdlib.builtins.RuntimeClasses.TryGetValue(name, out Type? cls))
            { result = cls; return true; }
            if (_type == typeof(Typhon.Stdlib.functools) && name == "partial") { result = typeof(PyPartial); return true; }
            if (_type.GetField(name, Members) is FieldInfo f)
            {
                result = f.GetValue(null);
                return !ReferenceEquals(result, Unbound);
            }
            if (_type.GetProperty(name, Members) is PropertyInfo p && p.GetIndexParameters().Length == 0)
            {
                try { result = p.GetValue(null); return true; }
                catch (TargetInvocationException e) when (p.IsDefined(typeof(PyLateAttributeAttribute)) && e.InnerException is NameError) { return false; }
            }
            if (_type.GetNestedType(name, BindingFlags.Public | BindingFlags.NonPublic) is Type nested &&
                PyConditionalModuleClassAttribute.IsBound(nested)) { result = nested; return true; }
            if (_type.GetMethods(Members).Any(m => m.Name == name && IsNamespaceMethod(m)))
            {
                var fn = _type.GetNestedType("__fn_" + name, BindingFlags.NonPublic)?.GetField("Instance", BindingFlags.Public | BindingFlags.Static);
                result = fn?.GetValue(null) ?? _methodValues.GetOrAdd(name, key => new PyBoundMethod(_type, key, includeNonPublic: true));
                return true;
            }
            return false;
        }

        internal bool TrySetNamespaceMember(string name, object? value)
        {
            if (_type?.GetField(name, Members) is FieldInfo field && !field.IsInitOnly && !field.IsLiteral)
            {
                Builtins.setattr(_type, name, value);
                return true;
            }
            if (_type?.GetProperty(name, Members) is PropertyInfo property && property.CanWrite &&
                property.IsDefined(typeof(PyLateAttributeAttribute)))
            {
                property.SetValue(null, value);
                return true;
            }
            return false;
        }

        internal bool TryDeleteNamespaceMember(string name)
        {
            if (_type?.GetField(name, Members) is not FieldInfo field ||
                !field.IsDefined(typeof(PyOptionalModuleMemberAttribute), false) || ReferenceEquals(field.GetValue(null), Unbound))
                return false;
            field.SetValue(null, Unbound);
            return true;
        }

        bool IsNamespaceMethod(MethodInfo method) => !method.IsSpecialName &&
            (_source == null || method.IsDefined(typeof(PySourceAttribute)));

        internal IEnumerable<string> NamespaceNames()
        {
            yield return "__name__";
            yield return "__doc__";
            if (__file__ != null) yield return "__file__";
            if (_type == null) yield break;
            if (_type == typeof(Typhon.Stdlib.builtins))
                foreach (string name in Typhon.Stdlib.builtins.RuntimeClasses.Keys) yield return name;
            foreach (var member in _type.GetMembers(Members))
                if (IsModuleName(member.Name) && (member is FieldInfo or PropertyInfo || member is MethodInfo method && IsNamespaceMethod(method)) &&
                    (member is not FieldInfo field || !field.IsDefined(typeof(PyOptionalModuleMemberAttribute), false) ||
                        !ReferenceEquals(field.GetValue(null), Unbound)) &&
                    (member is not PropertyInfo property || !property.IsDefined(typeof(PyLateAttributeAttribute)) || TryGetNamespaceMember(property.Name, out _)))
                    yield return member.Name;
            foreach (var nested in _type.GetNestedTypes(BindingFlags.Public | BindingFlags.NonPublic))
                if (IsModuleName(nested.Name) && PyConditionalModuleClassAttribute.IsBound(nested)) yield return nested.Name;
        }

        public override IEnumerable<string> GetDynamicMemberNames() => __dict__.Keys;
        public string __repr__() => (object?)__name__ is not string name ? "<module '?'>" :
            name == "__main__" ? "<module '__main__'>" : $"<module {Builtins.repr(name)} (built-in)>";
        public override string ToString() => __repr__();

        /// <summary>The standard modules of the runtime (Typhon.Stdlib's static classes, 'x_' named 'x') and __main__.</summary>
        internal static OrderedDictionary<string, object?> All(Type? mainModule = null)
        {
            var d = new OrderedDictionary<string, object?>();
            Type[] types;
            try { types = typeof(PyModule).Assembly.GetTypes(); }
            catch (ReflectionTypeLoadException e) { types = e.Types.Where(t => t != null).Select(t => t!).ToArray(); }
            foreach (var t in types.Where(t => t.Namespace == "Typhon.Stdlib" && !t.IsNested && t.IsAbstract && t.IsSealed).OrderBy(t => t.Name, StringComparer.Ordinal))
            {
                string name = t.Name.EndsWith('_') ? t.Name.Substring(0, t.Name.Length - 1) : t.Name;
                if (!d.ContainsKey(name)) d[name] = Of(t, name);
                foreach (var nested in t.GetNestedTypes().Where(n => n.IsAbstract && n.IsSealed && char.IsLower(n.Name[0])))
                    d.TryAdd(name + "." + nested.Name, Of(nested, name + "." + nested.Name));
            }
            d.TryAdd("builtins", Of(typeof(Builtins), "builtins"));
            mainModule ??= Assembly.GetEntryAssembly()?.GetType("__main__");
            d["__main__"] = mainModule == null ? new PyModule("__main__", null) : Of(mainModule, "__main__");
            return d;
        }
    }
}
